/bin/bash -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: Task.v
@@
 Proof.
-  intros R S t Hequiv; split; intros [Hlc [Hsn Hvalues]];
-    split; [exact Hlc|split; [exact Hsn|]];
-    intros result Hmulti Hvalue; apply Hequiv;
-    apply Hvalues; assumption.
+  intros R S t Hequiv; split; intros [Hlc [Hsn Hvalues]];
+    split; [exact Hlc|split; [exact Hsn|]];
+    intros result Hmulti Hvalue;
+    [apply (proj1 (Hequiv result))|apply (proj2 (Hequiv result))];
+    apply Hvalues; assumption.
*** End Patch
PATCH
timeout 10 coqc Task.v 2>&1; echo \"status: "'$?"'

